pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 amount) public {
        // We need an external party that behaves like a curated pool.
        // A simple helper that implements the minimal interface and passes
        // the onlyPool check by making isCuratedPool return true.
        vm.assume(amount > 0 && amount < type(uint128).max);
        address pool = address(new MockCuratedPool());
        vm.prank(pool);
        c.mintSynth(address(this), amount);
        uint256 lpBalance = c.getmapAddress_LPBalance(pool);
        uint256 lpDebt = c.getmapAddress_LPDebt(pool);
        assertTrue(lpBalance == lpDebt);
    }
}

contract MockCuratedPool {
    function isCuratedPool(address) external pure returns (bool) { return true; }
}

