    bool public revertOnBurn;

    constructor(C _synth, bool _revertOnBurn) {
        synth = _synth;
        revertOnBurn = _revertOnBurn;
    }

    function isCuratedPool(address caller) external view returns (bool) {
        return true;
    }

    function burn(uint256 amount) external {
        if (revertOnBurn) {
            revert("forced");
        }
    }

