pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address pool, uint256 lpAmount, uint256 mintAmount, address member) public {
        vm.assume(pool != address(0) && member != address(0));
        vm.assume(mintAmount > 0 && lpAmount > 0);
        // Set up pool as curated to satisfy onlyPool modifier
        // We need to mock the pool factory to say pool is curated.
        // Since onlyPool reads from DAO().POOLFACTORY().isCuratedPool, we deploy a fake pool factory that always returns true for this pool.
        // We cannot use vm.mockCall, so we deploy a minimal helper.
        FakePoolFactory factory = new FakePoolFactory();
        FakeDAO dao = new FakeDAO(address(factory));
        // C constructor expects BASE and LayerONE. We set BASE to address of fake DAO contract that returns the fake factory.
        // We deploy a new C with proper BASE so that _DAO() returns our fake DAO.
        // _DAO() reads iBASE(BASE).DAO(). We set BASE to a deployed FakeBase that returns our FakeDAO.
        FakeBase base = new FakeBase(address(dao));
        c = new C(address(base), pool);
        // Now give the pool some LP tokens to make _getAddedLPAmount return non-zero.
        // We need an actual token for the pool address that can transferFrom.
        // Use a simple ERC20 mock.
        MockERC20 poolToken = new MockERC20();
        // Override pool address with the mock token
        c = new C(address(base), address(poolToken));
        // But then pool address must be the token address for onlyPool modifier to receive msg.sender = token? No, onlyPool checks iPOOLFACTORY(_DAO().POOLFACTORY()).isCuratedPool(msg.sender).
        // So we need msg.sender to be curated. We will prank from pool.
        // However pool must have some LP balance to have _getAddedLPAmount return non-zero.
        // Transfer LP tokens to c.
        poolToken.mint(address(c), lpAmount);
        // Now we call mintSynth as the curated pool.
        vm.prank(pool);
        uint synthMinted = c.mintSynth(member, mintAmount);
        // The invariant: after mintSynth, mapSynth_LPDebt[pool] should increase by mintAmount.
        // Because the bug removes that line, mapSynth_LPDebt[pool] remains 0.
        // The general rule: mapSynth_LPDebt[pool] >= mintAmount after a successful mintSynth.
        assertTrue(c.getmapAddress_LPDebt(pool) >= mintAmount);
    }
}

contract FakeBase {
    address dao;
    constructor(address _dao) { dao = _dao; }
    function DAO() external view returns (address) { return dao; }
}

contract FakeDAO {
    address poolFactory;
    constructor(address _factory) { poolFactory = _factory; }
    function POOLFACTORY() external view returns (address) { return poolFactory; }
    function UTILS() external view returns (address) { return address(0); }
    function SYNTHFACTORY() external view returns (address) { return address(0); }
}

contract FakePoolFactory {
    function isCuratedPool(address) external pure returns (bool) { return true; }
}

contract MockERC20 {
    mapping(address => uint) public balanceOf;
    function mint(address to, uint amount) external { balanceOf[to] += amount; }
    function transferFrom(address, address, uint) external returns (bool) { return true; }
    function name() external pure returns (string memory) { return "Test"; }
    function symbol() external pure returns (string memory) { return "TST"; }
    function decimals() external pure returns (uint8) { return 18; }
    function allowance(address, address) external pure returns (uint) { return 0; }
    function transfer(address, uint) external returns (bool) { return true; }
    function approve(address, uint) external returns (bool) { return true; }
}

